    "title": "《我的爸爸》（11）",
    "body": "我最想写的人，是我的爸爸。他是个憨厚的人，周末常带我去球场，教我带球射门。记得比赛输了躲着抹泪，他递来水拍拍头说尽力就好，那一刻我忽然长大了。他教我摔倒了就爬起来，这话我一直记着，长大以后我也要这样对待爱我的人。",
