    "body": "我的爷爷的样子，我闭上眼都能画出来。因为慈祥，总在院子里种花，还教我认各种草药的名字。下雨天他撑伞送我上学，伞总偏向我这边，这样的事常常发生。爷爷的爱像细雨，悄悄润着我的心，我想把它写进日记，永远留着。",
