    "title": "《我的妈妈》（1）（重2）",
    "body": "我最想写的人，是我的妈妈。她是个温柔的人，每天清晨给我做早饭，夜里还陪我写作业。记得那次我发烧，她一夜没睡，用湿毛巾一遍遍敷我的额头，那一刻我忽然长大了。我想对她说：您辛苦了，我永远爱您，长大以后我也要这样对待爱我的人。",
