    "body": "我的爸爸陪我走过许多日子，我想写写TA。因为憨厚，周末常带我去球场，教我带球射门。比赛输了躲着抹泪，他递来水拍拍头说尽力就好，这样的事常常发生。他教我摔倒了就爬起来，这话我一直记着，长大以后我也要这样对待爱我的人。",
