    "title": "《我的奶奶》（37）（重2）",
    "body": "我最想写的人，是我的奶奶。她是个勤劳的人，天不亮就起来熬粥，把家里收拾得干干净净。记得我忘带文具，她跑着追到校门口递给我，那一刻我忽然长大了。奶奶的手很粗糙，却给了我最多的温暖，长大以后我也要这样对待爱我的人。",
